<?php
 namespace Pterodactyl\Services\Dezerx; class AdminTheme {private const STYLE_REV = 'c03ec9ee507c5f51550a010e8a2d6023';  public const MODE_KEY = 'admin_mode'; public const MODES = [ '' => 'Same as the client panel', 'dark' => 'Always dark', 'light' => 'Always light', ]; public const HINTS_KEY = 'admin_hints'; public const HINTS = [ '' => 'Beside the label, behind an (i)', 'inline' => 'Under the field, as written', ]; public const STYLESHEET = 'dezerx/admin/theme.css'; public const HINTS_SCRIPT = 'dezerx/admin/hints.js'; private const BUNDLED_FONTS = [ 'montserrat' => 'montserrat:400,500,600,700', 'plex-sans' => 'ibm-plex-sans:400,500,600,700', ]; private const BORDERS = [ 'subtle' => 'rgb(from var(--line-rgb) r g b / 0.08)', 'strong' => 'rgb(from var(--line-rgb) r g b / 0.2)', 'accent' => 'rgb(from var(--accent) r g b / 0.35)', ]; private const SHADOWS = [ 'none' => 'none', 'soft' => '0 6px 20px -12px rgb(0 0 0 / 0.45)', 'deep' => '0 18px 40px -18px rgb(0 0 0 / 0.6)', ]; private const FIELD_EDGE = '0.12'; public static function config(): ?array { if (!(Addons::get(Addons::ADMIN_THEME)['enabled'] ?? false)) { return null; } $appearance = Appearance::payload(); if ($appearance === []) { return null; } $theme = Theme::config(); return [ 'mode' => self::mode($theme), 'stylesheet' => self::asset(self::STYLESHEET), 'hints' => self::foldHints() ? self::asset(self::HINTS_SCRIPT) : null, 'tokens' => Appearance::css() . self::shapeCss($theme), 'motion' => [ 'button' => (string) $theme['button.animation'], 'page' => (string) $theme['page.transition'], 'active' => (string) $theme['sidebar.active'], ], 'fontHref' => self::fontHref($appearance['fonts']), 'presets' => Appearance::presetStyles(), 'defaultPreset' => $appearance['defaultPreset'], 'allowUserPresets' => $appearance['allowUserPresets'], 'logo' => $appearance['logo'], ]; } public static function mode(?array $theme = null): string { $mode = (string) (Addons::get(Addons::ADMIN_THEME)[self::MODE_KEY] ?? ''); if (!array_key_exists($mode, self::MODES)) { $mode = ''; } $pinned = (string) (($theme ?? Theme::config())['nav.colorMode'] ?? 'switch'); return $mode === '' && in_array($pinned, ['dark', 'light'], true) ? $pinned : $mode; } public static function foldHints(): bool { return (string) (Addons::get(Addons::ADMIN_THEME)[self::HINTS_KEY] ?? '') !== 'inline'; } private static function asset(string $file): string { $path = public_path($file); return '/' . $file . '?v=' . (is_file($path) ? filemtime($path) : 0); } private static function shapeCss(array $theme): string { $radius = (int) $theme['surface.radius']; $vars = [ 'radius-lg' => self::rem($radius * 0.5), 'radius-xl' => self::rem($radius * 0.75), 'radius-2xl' => self::rem($radius), 'radius-3xl' => self::rem($radius * 1.5), 'sa-card-border' => self::BORDERS[$theme['surface.border']] ?? 'transparent', 'field-edge' => $theme['surface.fieldBorder'] ? self::FIELD_EDGE : '0.02', ]; if (isset(self::SHADOWS[$theme['surface.shadow']])) { $vars['shadow-panel'] = self::SHADOWS[$theme['surface.shadow']]; } $body = ''; foreach ($vars as $name => $value) { $body .= "--{$name}:{$value};"; } return ":root{{$body}}"; } private static function fontHref(array $fonts): ?string { $families = []; foreach ($fonts as $id) { $bunny = self::BUNDLED_FONTS[$id] ?? Appearance::FONTS[$id]['bunny'] ?? null; if ($bunny !== null && !in_array($bunny, $families, true)) { $families[] = $bunny; } } return $families === [] ? null : 'https://fonts.bunny.net/css?family=' . implode('|', $families) . '&display=swap'; } private static function rem(float $px): string { return rtrim(rtrim(number_format($px / 16, 4, '.', ''), '0'), '.') . 'rem'; } } 